export interface Design {
  id: string;
  name: string;
  description: string;
  pdk: string;
  strategy: string;
  clock_mhz: number;
  status: string;
  rtl_code: string | null;
  testbench_code: string | null;
  sdc_code: string | null;
  spec_json: Record<string, unknown> | null;
  created_at: string;
  updated_at: string;
}

export interface PipelineRun {
  id: string;
  design_id: string;
  stage: string;
  status: string;
  failure_class: string | null;
  diagnostics: string[];
  metrics: Record<string, unknown>;
  artifacts: Record<string, unknown>;
  duration_ms: number;
  created_at: string;
}

export interface DesignArtifact {
  id: string;
  design_id: string;
  artifact_type: string;
  name: string;
  content: string | null;
  metadata: Record<string, unknown>;
  created_at: string;
}

