import { useState, useEffect, useCallback } from "react";
import { supabase } from "./supabase";
import type { Design, PipelineRun, DesignArtifact } from "./types";

export function useDesigns() {
  const [designs, setDesigns] = useState<Design[]>([]);
  const [loading, setLoading] = useState(true);

  const fetch = useCallback(async () => {
    setLoading(true);
    const { data } = await supabase
      .from("designs")
      .select("*")
      .order("created_at", { ascending: false });
    setDesigns(data ?? []);
    setLoading(false);
  }, []);

  useEffect(() => { fetch(); }, [fetch]);
  return { designs, loading, refetch: fetch };
}

export function useDesign(id: string | undefined) {
  const [design, setDesign] = useState<Design | null>(null);
  const [runs, setRuns] = useState<PipelineRun[]>([]);
  const [artifacts, setArtifacts] = useState<DesignArtifact[]>([]);
  const [loading, setLoading] = useState(true);

  const fetch = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    const [dRes, rRes, aRes] = await Promise.all([
      supabase.from("designs").select("*").eq("id", id).maybeSingle(),
      supabase.from("pipeline_runs").select("*").eq("design_id", id).order("created_at", { ascending: true }),
      supabase.from("design_artifacts").select("*").eq("design_id", id).order("created_at", { ascending: false }),
    ]);
    setDesign(dRes.data ?? null);
    setRuns(rRes.data ?? []);
    setArtifacts(aRes.data ?? []);
    setLoading(false);
  }, [id]);

  useEffect(() => { fetch(); }, [fetch]);
  return { design, runs, artifacts, loading, refetch: fetch };
}

export function useCreateDesign() {
  const [saving, setSaving] = useState(false);

  const create = async (fields: Partial<Design>) => {
    setSaving(true);
    const { data, error } = await supabase
      .from("designs")
      .insert(fields)
      .select()
      .maybeSingle();
    setSaving(false);
    if (error) throw error;
    return data as Design;
  };

  return { create, saving };
}

export function useUpdateDesign() {
  const update = async (id: string, fields: Partial<Design>) => {
    const { error } = await supabase
      .from("designs")
      .update({ ...fields, updated_at: new Date().toISOString() })
      .eq("id", id);
    if (error) throw error;
  };
  return { update };
}

export function useAddRun() {
  const add = async (run: Omit<PipelineRun, "id" | "created_at">) => {
    const { data, error } = await supabase
      .from("pipeline_runs")
      .insert(run)
      .select()
      .maybeSingle();
    if (error) throw error;
    return data as PipelineRun;
  };
  return { add };
}

export function useDashboardStats() {
  const [stats, setStats] = useState({ total: 0, passing: 0, failing: 0, running: 0 });

  useEffect(() => {
    (async () => {
      const { data } = await supabase.from("designs").select("status");
      if (!data) return;
      setStats({
        total: data.length,
        passing: data.filter((d) => d.status === "SUCCESS").length,
        failing: data.filter((d) => d.status === "FAIL").length,
        running: data.filter((d) => !["SUCCESS", "FAIL", "INIT"].includes(d.status)).length,
      });
    })();
  }, []);

  return stats;
}
